    },
    {
      "target_id": "t0",
      "policy_source_id": "q13",
      "policy_quote": "- Weight must be given in kilograms. If the customer gives pounds, convert (1 lb = 0.4536 kg) and round to one decimal.",
      "requirement": "The `weight_kg` argument must be a positive number with one decimal place (e.g., 2.4) and represent the weight in kilograms."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q13",
      "policy_quote": "- Prohibited items: batteries shipped loose (not inside a device), aerosols, and any liquids over 1 litre. Shipments containing prohibited items must not be created.",
      "requirement": "The `contents` argument must not describe prohibited items: loose batteries, aerosols, or liquids exceeding 1 liter."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q13",
      "policy_quote": "- Declared value (insurance) may not exceed 2,000 EUR per parcel. Values above that are not accepted.",
      "requirement": "If a `declared_value_eur` argument is provided, it must not exceed **2,000 EUR**. If omitted, no declared value is applied."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q13",
      "policy_quote": "- The service `express` guarantees next-business-day delivery; `standard` takes 2–4 business days.",
      "requirement": "The `service` argument must be one of the allowed values: **`standard`** or **`express`**."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q13",
      "policy_quote": "- Before `create_shipment`, ... obtain explicit confirmation (\"yes\"/\"да\").",
      "requirement": "Explicit confirmation from the user (exact phrase: **\"да\"** or **\"yes\"**) must be obtained **before** making the `create_shipment` call."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q13",
      "policy_quote": "- Look up the customer with `get_account` by account number. Act only on that account's shipments and saved addresses.",
      "requirement": "The `account_number` argument must match the account retrieved via `get_account` in the current session."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q13",
      "policy_quote": "- Outside the EU, customs declarations are required and declared value may go up to 5,000 EUR with the `international` service only. Not applicable to domestic shipments.",
      "requirement": "If the shipment is **domestic (EE to EE)**, the `declared_value_eur` argument (if provided) must not exceed **2,000 EUR**. If the shipment is **international**, the `service` must be **`international`**, and the `declared_value_eur` must not exceed **5,000 EUR**."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q13",
      "policy_quote": "- Pallet shipments over 30 kg are booked by the freight team.",
      "requirement": "If the `weight_kg` exceeds **30 kg**, the shipment must **not** be created via `create_shipment` (must be handled by the freight team)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q13",
      "policy_quote": "- Fragile items should be declared in `contents`; packaging advice is on the website.",
      "requirement": "If the shipment contains fragile items, the `contents` argument must include a description (e.g., **\"books (fragile)\"**)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q13",
      "policy_quote": "- Cash on delivery is not offered.",
      "requirement": "The `create_shipment` call must **not** include any cash-on-delivery options (not applicable here)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q13",
      "policy_quote": "- Pickups are between 09:00 and 18:00 on business days.",
      "requirement": "The pickup time (if specified elsewhere) must be between **09:00 and 18:00** on business days (Monday–Friday). **Not applicable to `create_shipment` arguments directly.**"
    }
